              : index === months.length - 1
                ? "end"
                : "middle"}
            class="chart-axis">{monthLabel(month.start)}</text
          >{/if}{/each}
      <text
        x="0"
        y={negative ? 335 : Math.min(335, baseline + 16)}
        class="chart-axis">{negative ? formatPounds(minimum) : "£0"}</text
